body{font-family:Arial, sans-serif;margin:0;padding:0;}
.board{display:flex;gap:1rem;padding:1rem;overflow:auto;}
.column{background:#f4f5f7;border-radius:4px;width:250px;display:flex;flex-direction:column;}
.column h3{margin:0;padding:8px 12px;background:#e2e4e6;border-bottom:1px solid #d0d1d2;}
.card-list{list-style:none;margin:0;padding:0;flex:1;min-height:50px;}
.card{background:white;margin:8px 12px;padding:8px;border-radius:3px;box-shadow:0 1px 0 rgba(9,30,66,.25);cursor:grab;}
.add-card-form{display:flex;gap:4px;padding:8px 12px;}
.add-card-form input{flex:1;padding:4px;}
.add-card-form button{padding:4px 8px;}

